import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity, Bell, CalendarDays, CheckCircle2, ChevronRight, CircleAlert, ClipboardList, FileClock,
  FileText, HeartPulse, LayoutDashboard, Menu, MessageCircle, Plus, Search, Settings,
  Sparkles, UserRound, UsersRound, X, PackageOpen, ReceiptIndianRupee, Library, Workflow,
} from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useTenant } from '../../context/TenantContext';
import { createExternalClient, listExternalClients } from '../../lib/fiteatsyConsultantsApi';
import ExternalTransientReportAnalyzer from './ExternalTransientReportAnalyzer';
import { ExternalClient360 } from './ExternalClient360';
import { ExternalAccountMenu } from './ExternalAccountMenu';
import { ExternalPracticeModule, PRACTICE_NAV } from './ExternalPracticeOperatingSystem';
import { ExternalCareOperations } from './ExternalCareOperations';
import { ExternalCommunicationWorkspace } from './ExternalCommunicationWorkspace';
import { ExternalCalendarWorkspace } from './ExternalCalendarWorkspace';
import { ExternalPracticeSettings } from './ExternalPracticeSettings';
import { ExternalIntelligentHome } from './ExternalIntelligentHome';
import { ExternalAssessments } from './ExternalAssessments';
import {ExternalTemplateLibrary} from './ExternalTemplateLibrary';
