const NAV = [
  ['dashboard', 'Dashboard', LayoutDashboard],
  ['clients', 'Clients', UsersRound],
  ['plans', 'Diet Plans', ClipboardList],
  ['reports', 'Reports', FileText],
  ['communication', 'Communication', MessageCircle],
  ['packages', 'Packages', PackageOpen],
  ['billing', 'Billing', ReceiptIndianRupee],
  ['resources', 'Resources', Library],
  ['automations', 'Automations', Workflow],
  ['referrals', 'Referrals', HeartPulse],
];
const SECONDARY_NAV=PRACTICE_NAV;
const REAL_P1_VIEWS=new Set(['consultations','followups','goals','tasks','checkins','adherence','notes']);
const FILTERS = ['All Accessible', 'My Clients', 'Unassigned', 'New', 'Intake Pending', 'Active', 'Follow-up Due', 'Diet Plan Pending', 'Inactive'];
const STATUS_LABEL = { ACTIVE: 'Active', INACTIVE: 'Inactive', INVITED: 'New', INTAKE_STARTED: 'Intake Pending', INTAKE_COMPLETED: 'Intake Complete' };

function initials(value=''){ return value.split(/\s+/).filter(Boolean).map(part=>part[0]).join('').slice(0,2).toUpperCase() || 'CL'; }
function toClientVM(client){
  const intake=client.intakeState==='COMPLETED'?'Complete':client.intakeState==='NOT_STARTED'?'Not started':`${client.intakeCompletionPercent||0}% complete`;
  return {
    ...client,
    displayStatus: STATUS_LABEL[client.status] || 'Active',
    intakeLabel: intake,
    goal: client.primaryGoal || 'Not provided',
    dietPlanLabel: client.dietPlanStatus ? client.dietPlanStatus.replaceAll('_',' ').toLowerCase() : 'No plan',
    latestReportLabel: client.latestReportAt ? new Date(client.latestReportAt).toLocaleDateString() : 'No report',
    lastActivityLabel: client.updatedAt ? new Date(client.updatedAt).toLocaleDateString() : 'Recently added',
  };
}

function StatusChip({children,tone='slate'}){
  const tones={slate:'bg-slate-100 text-slate-700',blue:'bg-blue-50 text-blue-700',amber:'bg-amber-50 text-amber-800',emerald:'bg-emerald-50 text-emerald-700'};
  return <span className={`inline-flex min-h-7 items-center rounded-full px-2.5 text-xs font-semibold ${tones[tone]}`}>{children}</span>;
}
function EmptyState({icon:Icon=Sparkles,title,copy,action,label}){return <div className="rounded-2xl border border-dashed border-slate-300 bg-white px-5 py-6 text-center"><span className="mx-auto grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon size={20}/></span><h3 className="mt-3 text-base font-bold text-slate-950">{title}</h3><p className="mx-auto mt-1.5 max-w-md text-sm leading-5 text-slate-600">{copy}</p>{action&&<button onClick={action} className="mt-4 min-h-11 rounded-xl bg-blue-700 px-5 text-sm font-semibold text-white hover:bg-blue-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-700 focus-visible:ring-offset-2">{label}</button>}</div>}
function SkeletonCards(){return <div aria-label="Loading workspace" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{Array.from({length:6},(_,i)=><div key={i} className="h-32 animate-pulse rounded-3xl border border-slate-200 bg-white p-5"><div className="h-3 w-20 rounded bg-slate-100"/><div className="mt-5 h-8 w-14 rounded bg-slate-100"/><div className="mt-4 h-3 w-32 rounded bg-slate-100"/></div>)}</div>}

export function ExternalSaaSWorkspace(){
  const {user}=useAuth(); const tenant=useTenant();
  const [view,setView]=useState('dashboard'); const [mobileNav,setMobileNav]=useState(false); const [notificationsOpen,setNotificationsOpen]=useState(false); const [clients,setClients]=useState([]); const [clientLoadState,setClientLoadState]=useState('loading'); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [query,setQuery]=useState(''); const [filter,setFilter]=useState('All Accessible'); const [selected,setSelected]=useState(null); const [initialTab,setInitialTab]=useState('Overview'); const [addOpen,setAddOpen]=useState(false);
  const [launcherOpen,setLauncherOpen]=useState(false);
  const [dashboardData,setDashboardData]=useState({resources:{},notifications:[],renewalSignals:[],unavailable:[]});const [dashboardState,setDashboardState]=useState('loading');const [dashboardError,setDashboardError]=useState('');
  const [practiceConfig,setPracticeConfig]=useState({profession:'OTHER',capabilities:[],terminology:{consultation:'Consultation',plan:'Care Plan',goal:'Goal'},profile:{}});
  const [teamAccess,setTeamAccess]=useState(null);
  const [clientAuthority,setClientAuthority]=useState({items:[],practice_wide:true,current_user_id:null});
  const practiceName=tenant.tenantName||user?.name||'My practice';
  const professionExperience=useMemo(()=>resolveProfessionExperience(practiceConfig.profession,practiceConfig),[practiceConfig]);
  const load=useCallback(async()=>{setLoading(true);setClientLoadState('loading');setDashboardState('loading');setError('');setDashboardError('');const resourceNames=['consultations','followups','goals','tasks','notifications','profession intelligence','renewals'];const [clientResult,configurationResult,projectionResult,...operations]=await Promise.allSettled([listExternalClients({limit:100}),getPracticeConfiguration(),listProfessionIntakeProjections(),...['consultations','follow-ups','goals','tasks'].map(resource=>listPracticeResources(resource,{limit:100})),listPracticeNotifications(),getProfessionIntelligence(),listRenewalSignals()]);if(clientResult.status==='fulfilled'&&Array.isArray(clientResult.value?.clients)){const projectionByClient=new Map((projectionResult.status==='fulfilled'?projectionResult.value?.items||[]:[]).map(item=>[String(item.client_id),item]));setClients(clientResult.value.clients.map(client=>{const projection=projectionByClient.get(String(client.id));return toClientVM(projection?{...client,intakeState:projection.status,intakeCompletionPercent:projection.completion_percent}:client);}));setClientLoadState('ready');}else{const reason=clientResult.status==='rejected'?clientResult.reason:null;setClientLoadState('error');setError(reason?.message||'Client records could not be loaded. Retry to restore the authoritative client list.');}if(configurationResult.status==='fulfilled')setPracticeConfig(configurationResult.value);const unavailable=resourceNames.filter((_,index)=>operations[index].status==='rejected');const value=index=>operations[index].status==='fulfilled'?operations[index].value:{items:[]};setDashboardData({resources:{consultations:value(0).items||[],followups:value(1).items||[],goals:value(2).items||[],tasks:value(3).items||[]},notifications:value(4).items||[],professionSignals:value(5).items||[],renewalSignals:value(6).items||[],unavailable});setDashboardState('ready');setDashboardError(unavailable.length?`${unavailable.join(', ')} unavailable`:'' );setLoading(false)},[]);
  useEffect(()=>{void load();},[load]);
  useEffect(()=>{Promise.all([getTeamAccess(),listMyClientAssignments()]).then(([access,authority])=>{setTeamAccess(access);setClientAuthority(authority)}).catch(()=>setTeamAccess(null))},[]);
  useEffect(()=>{const key=event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();setLauncherOpen(true)}if(event.key==='Escape')setLauncherOpen(false)};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)},[]);
  const visible=useMemo(()=>clients.filter(client=>{
    const haystack=`${client.displayName} ${client.email||''} ${client.mobile||''}`.toLowerCase();
    const searchMatch=!query||haystack.includes(query.toLowerCase());
    const assignments=clientAuthority.items||[];const allAssigned=new Set(assignments.map(item=>String(item.client_id)));const mine=new Set(assignments.filter(item=>String(item.user_id)===String(clientAuthority.current_user_id)).map(item=>String(item.client_id)));
    const filterMatch=filter==='All Accessible'||(filter==='My Clients'&&mine.has(String(client.id)))||(filter==='Unassigned'&&clientAuthority.practice_wide&&!allAssigned.has(String(client.id)))||(filter==='New'&&['INVITED'].includes(client.status))||(filter==='Intake Pending'&&client.status==='INTAKE_STARTED')||(filter==='Active'&&['ACTIVE','INTAKE_COMPLETED'].includes(client.status))||(filter==='Inactive'&&client.status==='INACTIVE')||(filter==='Diet Plan Pending'&&client.dietPlanLabel!=='published')||(filter==='Follow-up Due'&&client.followUpDue);
    return searchMatch&&filterMatch;
  }),[clientAuthority,clients,query,filter]);
  const openClient=(client,tab='Overview')=>{setSelected(client);setInitialTab(tab);setMobileNav(false);};
  const navigate=(next)=>{setSelected(null);setView(next);setMobileNav(false);};
  const professionNav=useMemo(()=>SECONDARY_NAV.filter(([id])=>{
    if(['consultations','followups','goals','tasks'].includes(id)) return professionExperience.care.includes(id);
    if(id==='assessments') return professionExperience.capabilities.has('ASSESSMENTS')||professionExperience.capabilities.has('assessments');
    if(id==='analytics') return teamAccess?.permissions?.includes('ANALYTICS_VIEW');
    return true;
  }).map(item=>item[0]==='consultations'?[item[0],`${professionExperience.terminology.consultation}s`,item[2]]:item[0]==='goals'?[item[0],`${professionExperience.terminology.goal}s & Progress`,item[2]]:item),[professionExperience,teamAccess]);
  const visibleNav=useMemo(()=>{const items=NAV.filter(([id])=>id!=='referrals'||teamAccess?.permissions?.includes('REFERRAL_VIEW'));if(teamAccess?.permissions?.includes('TEAM_VIEW'))items.push(['team','Team',UsersRound]);return items},[teamAccess]);
  const navigationItems=useMemo(()=>[...NAV,...professionNav].filter(([id])=>id!=='referrals'||teamAccess?.permissions?.includes('REFERRAL_VIEW')).concat(teamAccess?.permissions?.includes('TEAM_VIEW')?[['team','Team',UsersRound]]:[]),[professionNav,teamAccess]);
  const pageTitle=selected?.displayName||navigationItems.find(item=>item[0]===view)?.[1]||'Workspace';
  const pageSubtitle=selected?'Client 360':view==='clients'?'Manage authorised clients and onboarding progress.':view==='communication'?'WhatsApp templates and communication activity.':view==='plans'?'Current and historical client Diet Plans.':view==='reports'?'Transient lab analysis for an authorised client.':practiceName;
  return <div className={`${externalWorkspaceClass} min-h-screen bg-[#f4f6f8] text-slate-950`}>
    <a href="#external-main" className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[100] focus:rounded-lg focus:bg-white focus:px-4 focus:py-2">Skip to content</a>
    <aside className="fixed inset-y-0 left-0 z-40 hidden w-56 border-r border-white/10 bg-[#101827] text-white lg:flex lg:flex-col">
      <div className="border-b border-white/10 px-5 py-6"><p className="text-[11px] font-semibold uppercase tracking-[.2em] text-blue-300">Consultant practice</p><h1 className="mt-2 truncate text-lg font-bold">{practiceName}</h1><p className="mt-1 truncate text-xs text-slate-400">{tenant.tenantType?.replaceAll('_',' ')}</p></div>
      <nav aria-label="Primary" className="flex-1 space-y-1 overflow-y-auto p-3">{visibleNav.map(([id,label,Icon])=><button key={id} onClick={()=>navigate(id)} aria-current={!selected&&view===id?'page':undefined} className={`flex min-h-11 w-full items-center gap-3 rounded-xl px-3 text-sm font-semibold transition ${!selected&&view===id?'bg-white text-slate-950':'text-slate-300 hover:bg-white/10 hover:text-white'}`}><Icon size={18}/>{label}</button>)}<div className="my-3 border-t border-white/10"/><p className="px-3 pb-1 text-[10px] font-semibold uppercase tracking-widest text-slate-500">Practice tools</p>{professionNav.map(([id,label,Icon])=><button key={id} onClick={()=>navigate(id)} aria-current={!selected&&view===id?'page':undefined} className={`flex min-h-10 w-full items-center gap-3 rounded-xl px-3 text-sm transition ${!selected&&view===id?'bg-white text-slate-950':'text-slate-400 hover:bg-white/10 hover:text-white'}`}><Icon size={17}/>{label}</button>)}</nav>
      <div className="border-t border-white/10 p-4"><p className="truncate text-sm font-semibold">{user?.name||'Consultant'}</p><p className="mt-1 truncate text-xs text-slate-400">{user?.email||tenant.currentMembershipRole}</p></div>
    </aside>
    {mobileNav&&<div className="fixed inset-0 z-50 bg-slate-950/45 lg:hidden" onClick={()=>setMobileNav(false)}><aside aria-label="Mobile navigation" onClick={event=>event.stopPropagation()} className="h-full w-[min(84vw,320px)] overflow-y-auto bg-[#0c1728] p-4 text-white"><div className="mb-6 flex items-center justify-between"><strong className="truncate">{practiceName}</strong><button aria-label="Close navigation" onClick={()=>setMobileNav(false)} className="grid h-11 w-11 place-items-center rounded-xl bg-white/10"><X/></button></div>{navigationItems.map(([id,label,Icon])=><button key={id} onClick={()=>navigate(id)} className={`mb-1 flex min-h-12 w-full items-center gap-3 rounded-xl px-3 text-left font-semibold ${view===id&&!selected?'bg-white text-slate-950':'text-slate-200'}`}><Icon size={19}/>{label}</button>)}</aside></div>}
    <div className="lg:pl-56">
      <header className="sticky top-0 z-30 mx-2 mt-2 flex min-h-[76px] items-center justify-between rounded-2xl border border-white/80 bg-white/85 px-4 shadow-[0_10px_35px_-28px_rgba(15,23,42,.5)] backdrop-blur sm:mx-4 sm:px-5 xl:mx-6"><div className="flex min-w-0 items-center gap-3"><button onClick={()=>setMobileNav(true)} aria-label="Open navigation" className="grid h-11 w-11 place-items-center rounded-xl border border-slate-200 lg:hidden"><Menu size={20}/></button><div className="min-w-0"><h1 className="truncate text-xl font-semibold tracking-tight text-slate-950">{pageTitle}</h1><p className="truncate text-xs text-slate-500 sm:text-sm">{pageSubtitle}</p></div></div><div className="flex items-center gap-2">{!selected&&view==='clients'&&<button onClick={()=>setAddOpen(true)} className="hidden min-h-11 items-center gap-2 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white sm:inline-flex"><Plus size={16}/>Add Client</button>}<button aria-label="Open command search" onClick={()=>setLauncherOpen(true)} className="grid h-11 w-11 place-items-center rounded-xl border border-slate-200 bg-white text-slate-600"><Search size={18}/></button><button aria-label="Notifications" aria-expanded={notificationsOpen} onClick={()=>setNotificationsOpen(true)} className="relative grid h-11 w-11 place-items-center rounded-xl border border-slate-200 bg-white text-slate-600"><Bell size={18}/><span className="absolute right-2 top-2 h-2 w-2 rounded-full bg-blue-600"/></button><ExternalAccountMenu compact/></div></header>
      <main id="external-main" className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 xl:px-10 xl:py-9">
        {error&&<div role="alert" className="mb-5 flex items-center justify-between gap-3 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><span>{error}</span><button onClick={load} className="min-h-10 rounded-lg border border-red-300 px-3 font-semibold">Retry</button></div>}
        {selected?<ExternalClient360 client={selected} practiceName={practiceName} initialTab={initialTab} onBack={()=>setSelected(null)} onStatus={async()=>{await load();}}/>:clientLoadState==='error'?<section aria-label="Client list unavailable" className="rounded-3xl border border-amber-200 bg-amber-50 p-6"><h2 className="text-xl font-bold text-amber-950">Client list unavailable</h2><p className="mt-2 text-sm text-amber-900">No empty client state is shown because the authoritative client request did not complete successfully.</p><button onClick={load} className="mt-5 min-h-11 rounded-xl bg-amber-900 px-4 text-sm font-bold text-white">Retry client list</button></section>:view==='dashboard'?<ExternalIntelligentHome clients={clients} user={user} profession={practiceConfig.profession} data={dashboardData} state={dashboardState} error={dashboardError} onRetry={load} onAdd={()=>setAddOpen(true)} onNavigate={navigate} onOpen={openClient}/>:loading?<SkeletonCards/>:view==='clients'?<Clients clients={visible} allClients={clients} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} onAdd={()=>setAddOpen(true)} onOpen={openClient}/>:view==='team'?<ExternalTeam/>:view==='referrals'?<ExternalReferrals clients={clients}/>:view==='analytics'?<ExternalPracticeAnalytics activeClientCount={clients.filter(client=>client.status!=='INACTIVE').length}/>:view==='packages'?<ExternalPackages clients={clients}/>:view==='billing'?<ExternalBilling clients={clients}/>:view==='resources'?<ResourceLibrary clients={clients}/>:view==='automations'?<ExternalAutomations/>:view==='plans'?<PlanHistory clients={clients} onOpen={client=>openClient(client,'Diet Plan')}/>:view==='reports'?<Reports clients={clients} onOpen={client=>openClient(client,'Reports')}/>:view==='communication'?<ExternalCommunicationWorkspace clients={clients} practiceName={practiceName} consultantName={user?.name||'Consultant'} terminology={practiceConfig.terminology}/>:view==='calendar'?<ExternalCalendarWorkspace/>:view==='settings'?<ExternalPracticeSettings/>:view==='assessments'?<ExternalAssessments clients={clients}/>:view==='templates'?<ExternalTemplateLibrary/>:REAL_P1_VIEWS.has(view)?<ExternalCareOperations view={view} clients={clients} terminology={practiceConfig.terminology}/>:<ExternalPracticeModule view={view} clients={clients}/>} {/* external-only workspace boundary */}
      </main>
    </div>
    {addOpen&&<AddClientSheet onClose={()=>setAddOpen(false)} onCreated={async client=>{setAddOpen(false);await load();openClient(toClientVM(client));}}/>}
    {notificationsOpen&&<NotificationsDrawer clients={clients} onClose={()=>setNotificationsOpen(false)} onOpen={client=>{setNotificationsOpen(false);openClient(client);}}/>}
    {launcherOpen&&<CommandLauncher clients={clients} onClose={()=>setLauncherOpen(false)} onNavigate={next=>{setLauncherOpen(false);navigate(next)}} onOpen={client=>{setLauncherOpen(false);openClient(client)}}/>}
    {!selected&&<nav aria-label="Mobile primary" className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-5 border-t border-slate-200 bg-white pb-[env(safe-area-inset-bottom)] lg:hidden">{[['dashboard','Home',LayoutDashboard],['clients','Clients',UsersRound],['consultations','Care',HeartPulse],['calendar','Calendar',CalendarDays],['more','More',Menu]].map(([id,label,Icon])=><button key={id} onClick={()=>id==='more'?setMobileNav(true):navigate(id)} className={`min-h-16 py-2 text-xs font-semibold ${view===id?'text-blue-700':'text-slate-500'}`}><Icon className="mx-auto mb-1" size={20}/>{label}</button>)}</nav>}
  </div>;
}

function CommandLauncher({clients,onClose,onNavigate,onOpen}){const [term,setTerm]=useState('');const matches=clients.filter(client=>client.displayName.toLowerCase().includes(term.toLowerCase())).slice(0,5);const actions=[['Create client','clients'],['Schedule consultation','consultations'],['Create follow-up','followups'],['Review reports','reports'],['Open Diet Plans','plans']];return <div className="fixed inset-0 z-[70] bg-slate-950/50 p-3 sm:p-10" onClick={onClose}><section role="dialog" aria-modal="true" aria-label="Command search" onClick={event=>event.stopPropagation()} className="mx-auto max-w-2xl overflow-hidden rounded-3xl bg-white shadow-2xl"><label className="flex items-center gap-3 border-b px-5"><Search size={20}/><input autoFocus value={term} onChange={event=>setTerm(event.target.value)} placeholder="Find a client or action" className="min-h-16 w-full outline-none"/><span className="text-xs text-slate-400">Esc</span></label><div className="max-h-[65vh] overflow-y-auto p-3"><p className="px-3 py-2 text-xs font-bold uppercase tracking-wider text-slate-400">Quick actions</p>{actions.map(([label,target])=><button key={target} onClick={()=>onNavigate(target)} className="flex min-h-12 w-full items-center justify-between rounded-xl px-3 text-left font-semibold hover:bg-slate-50">{label}<ChevronRight size={17}/></button>)}{term&&<><p className="mt-3 px-3 py-2 text-xs font-bold uppercase tracking-wider text-slate-400">Clients</p>{matches.map(client=><button key={client.id} onClick={()=>onOpen(client)} className="flex min-h-12 w-full items-center justify-between rounded-xl px-3 text-left hover:bg-slate-50"><span className="font-semibold">{client.displayName}</span><ChevronRight size={17}/></button>)}</>}</div></section></div>}

function Dashboard({clients,user,onAdd,onNavigate,onOpen}){
  const intakePending=clients.filter(c=>c.status==='INTAKE_STARTED'||c.status==='INVITED'); const planPending=clients.filter(c=>c.dietPlanLabel!=='published');
  const stats=[['Active clients',clients.filter(c=>c.status!=='INACTIVE').length,UsersRound],['Intake pending',intakePending.length,ClipboardList],['Reports to review',clients.filter(c=>c.reportNeedsReview).length,FileText],['Draft Diet Plans',planPending.length,FileClock],['Follow-ups due',clients.filter(c=>c.followUpDue).length,CalendarDays]];
  return <div className="space-y-7"><section className="flex flex-col justify-between gap-5 rounded-[28px] bg-gradient-to-br from-[#0c1728] via-[#10294b] to-[#174f7e] p-6 text-white sm:p-8 lg:flex-row lg:items-end"><div><p className="text-sm text-blue-200">{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h2 className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">Good {new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, {(user?.name||'Consultant').split(' ')[0]}</h2><p className="mt-2 text-blue-100">Here’s what needs your attention today.</p></div><div className="flex flex-wrap gap-2"><button onClick={onAdd} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950"><Plus size={16} className="mr-2 inline"/>Add Client</button><button onClick={()=>onNavigate('clients')} className="min-h-11 rounded-xl border border-white/25 px-4 text-sm font-bold">Invite Client</button></div></section><section aria-label="Practice summary" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{stats.map(([label,value,Icon])=><article key={label} className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon size={19}/></span><p className="mt-5 text-3xl font-bold">{value}</p><p className="mt-1 text-sm text-slate-600">{label}</p></article>)}</section><div className="grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><section className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center justify-between"><div><h3 className="text-xl font-bold">Needs your attention</h3><p className="mt-1 text-sm text-slate-500">Prioritised care work, not reporting noise.</p></div><StatusChip tone="amber">{Math.min(intakePending.length+planPending.length,9)} open</StatusChip></div><div className="mt-5 space-y-3">{[...intakePending.slice(0,2).map(c=>[c,'Client intake incomplete','Open Client','Overview']),...planPending.slice(0,3).map(c=>[c,'Diet Plan needs attention','Continue Plan','Diet Plan'])].slice(0,5).map(([client,message,cta,tab],index)=><button key={`${client.id}-${index}`} onClick={()=>onOpen(client,tab)} className="flex min-h-16 w-full items-center justify-between gap-4 rounded-2xl border border-slate-100 bg-slate-50 px-4 text-left hover:border-blue-200 hover:bg-blue-50"><div className="min-w-0"><p className="truncate font-semibold">{client.displayName}</p><p className="text-sm text-slate-600">{message}</p></div><span className="shrink-0 text-sm font-bold text-blue-700">{cta}<ChevronRight size={16} className="ml-1 inline"/></span></button>)}{clients.length===0&&<p className="py-8 text-center text-sm text-slate-500">Add your first client to start the attention queue.</p>}</div></section><section className="space-y-6"><div className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="text-lg font-bold">Today</h3><EmptyState icon={CalendarDays} title="A clear schedule" copy="No consultations or follow-ups are due today."/></div><div className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="text-lg font-bold">Recent activity</h3><div className="mt-4 space-y-4">{clients.slice(0,4).map(client=><div key={client.id} className="flex gap-3"><span className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-blue-600"/><div><p className="text-sm font-semibold">{client.displayName} added</p><p className="text-xs text-slate-500">{client.lastActivityLabel}</p></div></div>)}{clients.length===0&&<p className="text-sm text-slate-500">No client activity yet.</p>}</div></div></section></div></div>;
}

function Clients({clients,allClients,query,setQuery,filter,setFilter,onAdd,onOpen}){
  const complete=allClients.filter(client=>client.intakeState==='COMPLETED').length;
  const inProgress=allClients.filter(client=>client.intakeState!=='COMPLETED').length;
  const attention=allClients.filter(client=>client.reportNeedsReview||client.followUpDue||client.intakeState!=='COMPLETED').length;
  const metrics=[['Active clients',allClients.filter(client=>client.status!=='INACTIVE').length,UsersRound,'blue'],['Onboarding complete',complete,CheckCircle2,'emerald'],['Onboarding in progress',inProgress,ClipboardList,'amber'],['Needs attention',attention,CircleAlert,'rose']];
  return <div className="space-y-4 rounded-[30px] border border-white/80 bg-[#ecebe6] p-3 shadow-[0_28px_70px_-58px_rgba(15,23,42,.55)] sm:p-5"><Surface density="standard" className="border-white/80 bg-[#f9f8f4] shadow-none"><PageHeader eyebrow="Client command centre" title="Clients" subtitle="Manage active clients, onboarding progress, priorities, and next actions." actions={<Button variant="primary" icon={Plus} onClick={onAdd}>Add Client</Button>}/></Surface>
    <section aria-label="Client metrics" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{metrics.map(([label,value,Icon,tone],index)=><Surface key={label} density="compact" className={`flex min-h-[104px] items-center gap-4 border-white/80 shadow-sm ${index===0?'bg-slate-950 text-white sm:col-span-2 xl:col-span-3':'bg-white xl:col-span-1'}`}><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl border ${index===0?'border-white/10 bg-white/10 text-blue-200':tone==='emerald'?'border-emerald-200 bg-emerald-50 text-emerald-700':tone==='amber'?'border-amber-200 bg-amber-50 text-amber-700':tone==='rose'?'border-rose-200 bg-rose-50 text-rose-700':'border-blue-200 bg-blue-50 text-blue-700'}`}><Icon size={18}/></span><div><p className={`text-xs font-semibold uppercase tracking-[.08em] ${index===0?'text-slate-400':'text-slate-500'}`}>{label}</p><p className={`mt-1 font-semibold tracking-[-.05em] ${index===0?'text-4xl text-white':'text-3xl text-slate-950'}`}>{value}</p></div></Surface>)}</section>
    <Surface density="standard" className="overflow-hidden border-slate-200 p-0 shadow-[0_10px_30px_rgba(15,23,42,.06)]"><div className="border-b border-slate-200 bg-white p-4 sm:p-5"><div className="flex flex-col gap-3 lg:flex-row lg:items-center"><label className="relative min-w-0 flex-1"><Search className="absolute left-3.5 top-3.5 text-slate-400" size={18}/><input aria-label="Search clients" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search by name, mobile or email" className="min-h-12 w-full rounded-xl border border-slate-200 bg-slate-50 pl-11 pr-4 outline-none focus:border-blue-600 focus:bg-white focus:ring-2 focus:ring-blue-100"/></label><div className="flex items-center justify-between gap-3"><span className="whitespace-nowrap text-xs font-medium text-slate-500">{clients.length} of {allClients.length} clients</span>{(query||filter!=='All Accessible')&&<button onClick={()=>{setQuery('');setFilter('All Accessible')}} className="min-h-11 whitespace-nowrap rounded-xl px-3 text-xs font-semibold text-blue-700">Clear filters</button>}</div></div><div className="mt-3 flex gap-2 overflow-x-auto pb-1" aria-label="Client filters">{FILTERS.map(item=><button key={item} onClick={()=>setFilter(item)} aria-pressed={filter===item} className={`min-h-11 shrink-0 rounded-xl border px-3.5 text-xs font-semibold transition ${filter===item?'border-slate-950 bg-slate-950 text-white':'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'}`}>{item}</button>)}</div></div>
      {allClients.length===0?<div className="p-5"><EmptyState icon={UsersRound} title="Start with your first client" copy="Add a client directly or send a secure invitation to begin their health profile." action={onAdd} label="Add Client"/></div>:clients.length===0?<div className="p-10 text-center text-sm text-slate-500">No clients match this search and filter.</div>:<div><div className="hidden grid-cols-[1.45fr_.9fr_1.1fr_.9fr_auto] gap-4 border-b border-slate-200 bg-slate-50 px-5 py-3 text-[11px] font-semibold uppercase tracking-[.08em] text-slate-500 lg:grid"><span>Client</span><span>Status</span><span>Onboarding</span><span>Last activity</span><span>Next action</span></div><div className="divide-y divide-slate-100">{clients.map(client=>{const pct=client.intakeState==='COMPLETED'?100:Number(client.intakeCompletionPercent)||0;const next=client.intakeState!=='COMPLETED'?'Review onboarding':'Open client';return <button key={client.id} onClick={()=>onOpen(client)} className="group grid min-h-[144px] w-full gap-4 px-4 py-4 text-left transition hover:bg-slate-50 sm:px-5 lg:min-h-[92px] lg:grid-cols-[1.45fr_.9fr_1.1fr_.9fr_auto] lg:items-center"><div className="flex min-w-0 items-center gap-3"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-blue-50 font-bold text-blue-700">{initials(client.displayName)}</span><div className="min-w-0"><p className="truncate font-semibold text-slate-950">{client.displayName}</p><p className="truncate text-xs text-slate-500">{client.email||client.mobile||'No contact provided'}</p></div></div><div className="flex items-center justify-between lg:block"><span className="text-[11px] font-medium uppercase tracking-wide text-slate-400 lg:hidden">Status</span><StatusChip tone={client.status==='ACTIVE'?'emerald':client.status==='INTAKE_STARTED'?'amber':'blue'}>{client.displayStatus}</StatusChip></div><div className="min-w-0"><div className="mb-1.5 flex items-center justify-between gap-2 text-xs"><span className="font-medium text-slate-700">{client.intakeState==='COMPLETED'?'Complete':pct===0?'Not started':'In progress'}</span><span className="font-semibold text-slate-950">{pct}%</span></div><ProgressBar value={pct}/></div><div className="flex items-center justify-between text-xs lg:block"><span className="font-medium uppercase tracking-wide text-slate-400 lg:hidden">Last activity</span><span className="text-slate-600">{client.lastActivityLabel}</span></div><span className="flex min-h-11 items-center justify-between rounded-xl bg-slate-950 px-4 text-xs font-semibold text-white lg:bg-transparent lg:px-0 lg:text-blue-700">{next}<ChevronRight size={16} className="transition group-hover:translate-x-0.5"/></span></button>})}</div></div>}
    </Surface>
  </div>;
}

function PlanHistory({clients,onOpen}){const withPlans=clients.filter(client=>client.dietPlanStatus);return <div><div><h2 className="text-3xl font-bold tracking-tight">Diet Plans</h2><p className="mt-2 text-sm text-slate-600">Current drafts, published plans and exact historical versions.</p></div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_360px]"><section className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="text-lg font-bold">Current plans</h3>{withPlans.length?<div className="mt-4 divide-y divide-slate-100">{withPlans.map(client=><button key={client.id} onClick={()=>onOpen(client)} className="flex min-h-20 w-full items-center justify-between gap-4 py-3 text-left"><div><p className="font-bold">{client.displayName}</p><p className="mt-1 text-sm capitalize text-slate-500">{client.dietPlanLabel}</p></div><span className="font-semibold text-blue-700">Open workspace <ChevronRight className="inline" size={16}/></span></button>)}</div>:<EmptyState icon={ClipboardList} title="No Diet Plans yet" copy="Create a personalised plan using a client’s profile and governed food options."/>}</section><aside className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="text-lg font-bold">Version history</h3><p className="mt-2 text-sm leading-6 text-slate-500">Open a client’s Diet Plan workspace to view, compare, download, or duplicate an exact historical version.</p><div className="mt-5 border-l-2 border-slate-200 pl-4"><p className="font-semibold">Published versions</p><p className="mt-1 text-sm text-slate-500">Immutable and downloadable</p><p className="mt-5 font-semibold">Draft versions</p><p className="mt-1 text-sm text-slate-500">Editable and clearly separated</p></div></aside></div></div>}
function Reports({clients,onOpen}){const [clientId,setClientId]=useState('');const [message,setMessage]=useState('');const selected=clients.find(client=>client.id===clientId);return <div><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-3xl font-bold tracking-tight">Lab analysis</h2><p className="mt-2 text-sm text-slate-600">Select an authorised client, analyze the report transiently, then review the extracted biomarkers before saving.</p></div>{selected&&<button onClick={()=>onOpen(selected)} className="min-h-11 rounded-xl border border-slate-200 px-4 text-sm font-bold text-blue-700">Open Client 360</button>}</div><label className="mt-6 block rounded-2xl border border-slate-200 bg-white p-5 text-sm font-semibold">Client<select required aria-label="Select client for report" value={clientId} onChange={event=>{setClientId(event.target.value);setMessage('');}} className="mt-2 min-h-12 w-full rounded-xl border border-slate-200 bg-white px-3"><option value="">Search / select client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label>{selected?<div className="mt-4"><ExternalTransientReportAnalyzer clientId={selected.id} onSaved={async()=>setMessage('Reviewed biomarkers saved to the selected client profile.')} onError={setMessage}/></div>:<div className="mt-4"><EmptyState icon={FileText} title="Choose a client first" copy="Report analysis is always scoped to one authorised External client."/></div>}{message&&<p role="status" className="mt-4 rounded-xl bg-blue-50 px-4 py-3 text-sm text-blue-900">{message}</p>}</div>}
const CAPABILITIES={consultations:['Consultations','Upcoming, completed and follow-up consultation workspaces are prepared here.',CalendarDays],followups:['Follow-ups','Due today, upcoming, overdue and completed follow-ups will appear here.',FileClock],tasks:['Tasks','Track report reviews, Diet Plan work, measurements and client follow-ups.',ClipboardList],templates:['Templates','Reusable clinical templates will become available when the governed template service is enabled.',Sparkles],analytics:['Analytics','Practice analytics will appear after the reporting capability is enabled.',Activity],settings:['Settings & Branding','Practice branding, account preferences and organisation controls will appear here.',Settings]};
function CapabilityShell({view}){const [title,copy,Icon]=CAPABILITIES[view]||CAPABILITIES.tasks;return <div><h2 className="text-3xl font-bold tracking-tight">{title}</h2><p className="mt-2 text-sm text-slate-600">{copy}</p><div className="mt-6"><EmptyState icon={Icon} title={`${title} is ready for capability activation`} copy="This workspace is intentionally available as a controlled empty state. No action is shown until the matching governed backend capability is enabled."/></div></div>}
function NotificationsDrawer({clients,onClose,onOpen}){const items=clients.filter(client=>client.status==='INTAKE_STARTED'||client.dietPlanLabel!=='published').slice(0,8);return <div className="fixed inset-0 z-50 flex justify-end bg-slate-950/40" onClick={onClose}><section role="dialog" aria-modal="true" aria-labelledby="notifications-title" onClick={event=>event.stopPropagation()} className="h-full w-full max-w-md overflow-y-auto bg-white p-5 shadow-2xl sm:p-7"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Practice activity</p><h2 id="notifications-title" className="mt-1 text-2xl font-bold">Notifications</h2></div><button onClick={onClose} aria-label="Close notifications" className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div><div className="mt-7 space-y-3">{items.length?items.map(client=><button key={client.id} onClick={()=>onOpen(client)} className="w-full rounded-2xl border border-slate-200 p-4 text-left hover:border-blue-300"><p className="font-bold">{client.displayName}</p><p className="mt-1 text-sm text-slate-500">{client.status==='INTAKE_STARTED'?'Health profile needs attention':'Diet Plan needs attention'}</p><span className="mt-3 inline-block text-sm font-bold text-blue-700">Open client →</span></button>):<EmptyState icon={Bell} title="You’re all caught up" copy="New report, intake, Diet Plan and follow-up activity will appear here."/>}</div></section></div>}
function AddClientSheet({onClose,onCreated}){const [form,setForm]=useState({firstName:'',lastName:'',mobile:'',email:''});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const save=async event=>{event.preventDefault();setBusy(true);setError('');try{const result=await createExternalClient(form);onCreated(result.client);}catch(e){setError(e.message||'Unable to add client.');setBusy(false);}};return <div className="fixed inset-0 z-50 flex justify-end bg-slate-950/40" onClick={onClose}><form onSubmit={save} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="add-client-title" className="h-full w-full max-w-lg overflow-y-auto bg-white p-5 shadow-2xl sm:p-8"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Client management</p><h2 id="add-client-title" className="mt-2 text-2xl font-bold">Add client</h2></div><button type="button" onClick={onClose} aria-label="Close" className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div><p className="mt-3 text-sm text-slate-600">Create a client record, then invite them to complete their health profile securely.</p>{error&&<p role="alert" className="mt-5 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="mt-7 grid gap-5 sm:grid-cols-2">{[['First name','firstName','text'],['Last name','lastName','text'],['Mobile','mobile','tel'],['Email','email','email']].map(([label,key,type])=><label key={key} className="text-sm font-semibold">{label}<input required={key==='firstName'||key==='lastName'} type={type} value={form[key]} onChange={event=>setForm({...form,[key]:event.target.value})} className="mt-2 min-h-12 w-full rounded-xl border border-slate-200 px-3 outline-none focus:border-blue-600 focus:ring-2 focus:ring-blue-100"/></label>)}</div><div className="sticky bottom-0 mt-10 flex gap-3 border-t bg-white py-4"><button type="button" onClick={onClose} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button disabled={busy||(!form.mobile&&!form.email)} className="min-h-12 flex-1 rounded-xl bg-blue-700 font-bold text-white disabled:opacity-40">{busy?'Adding…':'Add client'}</button></div></form></div>}
